package com.muthumol.player.dummy;
import android.content.*;import android.os.*;import java.util.*;import java.util.concurrent.*;import org.json.*;import org.drinkless.tdlib.TdApi;
/** Account scoped progress records in the user's own Saved Messages. No media IDs travel. */
final class WatchSync {
 static final String TAG="TGSTREAM_WATCH_V1";static WatchSync instance;
 static synchronized WatchSync get(Context c){if(instance==null)instance=new WatchSync(c.getApplicationContext());return instance;}
 final Context c;final SharedPreferences p;final TelegramBridge tg;final TelegramLibrary.Calls calls;final Handler ui=new Handler(Looper.getMainLooper());final ExecutorService worker=Executors.newSingleThreadExecutor();boolean busy;long lastPull,lastPush;String status="Waiting for Telegram";long self;
 WatchSync(Context c){this(c,TelegramBridge.getInstance(c)::waitRequest);}
 WatchSync(Context c,TelegramLibrary.Calls calls){this.c=c;p=c.getSharedPreferences("watch-sync",0);tg=TelegramBridge.getInstance(c);this.calls=calls;}
 static String key(Movie m){return m.chatId+"_"+m.messageId;}
 static JSONObject newer(JSONObject a,JSONObject b){return a==null||b.optLong("updated")>a.optLong("updated")?b:a;}
 synchronized void record(Movie m,long position,long duration,Boolean watched){if(m.chatId==0||m.messageId==0)return;try{String k=key(m);JSONObject old=new JSONObject(p.getString("state:"+k,"{}"));JSONObject state=new JSONObject().put("chat",m.chatId).put("message",m.messageId).put("position",Math.max(0,position)).put("duration",Math.max(0,duration)).put("watched",watched!=null?watched:old.optBoolean("watched")).put("updated",System.currentTimeMillis());p.edit().putString("state:"+k,state.toString()).putBoolean("dirty:"+k,true).apply();schedulePush();}catch(Exception ignored){}}
 synchronized void removeHistory(Movie m){record(m,0,m.duration*1000L,null);try{String k=key(m);JSONObject value=local(k);if(value!=null){value.put("historyRemoved",true);p.edit().putString("state:"+k,value.toString()).putBoolean("dirty:"+k,true).apply();}}catch(Exception ignored){}}
 boolean pushScheduled;void schedulePush(){if(pushScheduled)return;pushScheduled=true;ui.postDelayed(push,30000);}
 final Runnable push=()->{pushScheduled=false;sync(null,true);};
 void refresh(){sync(null,false);}
 void beforePlay(Runnable next){final boolean[] done={false};Runnable once=()->{if(done[0])return;done[0]=true;next.run();};ui.postDelayed(once,8000);sync(once,false);}
 void sync(Runnable after,boolean force){if(!tg.ready){if(after!=null)after.run();return;}if(busy){if(after!=null)ui.postDelayed(()->sync(after,force),250);return;}if(!force&&SystemClock.elapsedRealtime()-lastPull<15000){if(after!=null)after.run();return;}busy=true;status="Syncing watch progress…";worker.execute(()->{try{if(self==0){TdApi.Object me=calls.call("GetMe");long user=TelegramBridge.num(me,"id");long owner=p.getLong("owner",0);if(owner!=0&&owner!=user)p.edit().clear().apply();p.edit().putLong("owner",user).apply();TdApi.Object chat=calls.call("CreatePrivateChat","userId",user,"force",false);if(chat instanceof TdApi.Error)throw new Exception(TelegramBridge.str(chat,"message"));self=TelegramBridge.num(chat,"id");}if(self==0)throw new Exception("Saved Messages unavailable");long from=0;Set<Long> seen=new HashSet<>();while(true){TdApi.Object page=calls.call("SearchChatMessages","chatId",self,"topicId",null,"query",TAG,"senderId",null,"fromMessageId",from,"offset",0,"limit",100,"filter",TelegramBridge.obj("SearchMessagesFilterEmpty"));if(page instanceof TdApi.Error)throw new Exception(TelegramBridge.str(page,"message"));Object raw=TelegramBridge.get(page,"messages");if(!(raw instanceof TdApi.Message[]))throw new Exception("Unexpected progress response");for(TdApi.Message msg:(TdApi.Message[])raw){String text=TelegramBridge.str(TelegramBridge.get(msg.content,"text"),"text");if(!text.startsWith(TAG+"\n"))continue;try{JSONObject remote=new JSONObject(text.substring(TAG.length()+1));long chat=remote.optLong("chat"),message=remote.optLong("message");if(chat==0||message==0)continue;String k=chat+"_"+message;JSONObject local=local(k);if(newer(local,remote)==remote){TdApi.Object source=calls.call("GetMessage","chatId",chat,"messageId",message);Movie resolved=Movie.fromMessage(source,chat);if(resolved!=null)synchronized(WatchSync.this){if(newer(local(k),remote)==remote){apply(remote,resolved);p.edit().putString("state:"+k,remote.toString()).putBoolean("dirty:"+k,false).apply();}}}if(remote.optLong("updated")>=p.getLong("cloudUpdated:"+k,0))p.edit().putLong("cloud:"+k,msg.id).putLong("cloudUpdated:"+k,remote.optLong("updated")).apply();}catch(JSONException ignored){}}long next=TelegramBridge.num(page,"nextFromMessageId");if(next<=0||next==from||!seen.add(next))break;from=next;}lastPull=SystemClock.elapsedRealtime();int sent=0;for(Map.Entry<String,?> e:p.getAll().entrySet()){if(!e.getKey().startsWith("dirty:")||!Boolean.TRUE.equals(e.getValue()))continue;if(sent++>=4){ui.postDelayed(push,60000);break;}String k=e.getKey().substring(6);JSONObject state=local(k);if(state==null)continue;String snapshot=state.toString();Object text=TelegramBridge.obj("FormattedText","text",TAG+"\n"+snapshot,"entities",new TdApi.TextEntity[0]);Object content=TelegramBridge.obj("InputMessageText","text",text,"linkPreviewOptions",null,"clearDraft",false);long id=p.getLong("cloud:"+k,0);TdApi.Object result=id>0?calls.call("EditMessageText","chatId",self,"messageId",id,"replyMarkup",null,"inputMessageContent",content):calls.call("SendMessage","chatId",self,"topicId",null,"replyTo",null,"options",null,"replyMarkup",null,"inputMessageContent",content);if(result instanceof TdApi.Error){String error=TelegramBridge.str(result,"message");if(!error.contains("MESSAGE_NOT_MODIFIED"))throw new Exception(error);}else{long cloud=TelegramBridge.num(result,"id");if(cloud>0)p.edit().putLong("cloud:"+k,cloud).apply();}if(snapshot.equals(p.getString("state:"+k,"")))p.edit().putBoolean("dirty:"+k,false).apply();}status="Watch progress synced";lastPush=SystemClock.elapsedRealtime();}catch(Exception e){status="Progress sync pending · "+e.getMessage();ui.removeCallbacks(push);ui.postDelayed(push,60000);}finally{ui.post(()->{busy=false;if(after!=null)after.run();});}});}
 JSONObject local(String key){try{String raw=p.getString("state:"+key,"");return raw.isEmpty()?null:new JSONObject(raw);}catch(Exception e){return null;}}
 void apply(JSONObject state,Movie m){if(state.optBoolean("historyRemoved")){TvLibrary library=new TvLibrary(c);library.p.edit().remove("movie:"+library.key(m)).apply();c.getSharedPreferences("history-hidden",0).edit().putBoolean(m.cacheIdentity(),true).apply();}else new TvLibrary(c).remember(m);VideoCopies.save(c,m,state.optLong("position"),state.optLong("duration"));c.getSharedPreferences("player",0).edit().putLong("pos:"+m.cacheIdentity(),state.optLong("position")).putLong("duration:"+m.cacheIdentity(),state.optLong("duration")).apply();TvLibrary lib=new TvLibrary(c);lib.p.edit().putBoolean(lib.markKey(m,"watched"),state.optBoolean("watched")).apply();}
}
